package com.autobase.main.Vehicle;

import java.io.Serializable;

public class Driver implements Serializable {
    private static final long serialVersionUID = 1L;

    private String name;
    private int experience;

    public Driver(String n, int exp) {
        this.name = n;
        this.experience = exp;
    }

    public Driver() {
        this("", 0);
    }

    public void addExperience(int years) {
        this.experience += years;
    }

    public void print() {
        System.out.println("Driver: " + name + ", experience: " + experience + " years");
    }

    @Override
    public String toString() {
        return "Driver{" +
                "name='" + name + '\'' +
                ", experience=" + experience +
                '}';
    }

    public String getName() {
        return name;
    }

    public int getExperience() {
        return experience;
    }

}

package com.autobase.main.Vehicle;

import java.io.*;

public class Driver implements Externalizable {
    private static final long serialVersionUID = 1L;

    private String name;
    private int experience;

    public Driver(String n, int exp) {
        this.name = n;
        this.experience = exp;
    }

    public Driver() {
        this("", 0);
    }

    @Override
    public void writeExternal(ObjectOutput out) throws IOException {
        out.writeUTF(name != null ? name : "");
        out.writeInt(experience);
    }

    @Override
    public void readExternal(ObjectInput in) throws IOException, ClassNotFoundException {
        this.name = in.readUTF();
        this.experience = in.readInt();
    }

    public void addExperience(int years) {
        this.experience += years;
    }

    public void print() {
        System.out.println("Driver: " + name + ", experience: " + experience + " years");
    }

    @Override
    public String toString() {
        return "Driver{" +
                "name='" + name + '\'' +
                ", experience=" + experience +
                '}';
    }

    public String getName() {
        return name;
    }

    public int getExperience() {
        return experience;
    }

}

package com.autobase.main.order;

import com.autobase.main.order.typeoforder.CargoType;
import com.autobase.main.Vehicle.Vehicle;

import java.io.Serializable;
import java.util.List;

public abstract class Order implements Serializable {
    private static final long serialVersionUID = 1L;

    protected String from;
    protected String to;
    protected CargoType cargoType;
    protected float cargoWeight;
    protected Vehicle vehicle;

    public static float GLOBAL_RATE = 1.0f;

    public Order() {}

    public abstract void input();

    public abstract void print();

    @Override
    public abstract String toString();

    public boolean canMergeWith(Order other) {
        return this.cargoType == other.cargoType && this.to.equals(other.to);
    }

    public void mergeWeight(float w) {
        this.cargoWeight += w;
    }

    public int loadFields(List<String> fields, int startIndex) {
        int i = startIndex;
        this.from = fields.get(i++);
        this.to = fields.get(i++);
        this.cargoType = CargoType.valueOf(fields.get(i++));
        this.cargoWeight = Float.parseFloat(fields.get(i++));
        return i;
    }

    public String getFrom() {
        return from;
    }

    public String getTo() {
        return to;
    }

    public CargoType getCargoType() {
        return cargoType;
    }

    public float getWeight() {
        return cargoWeight;
    }

    public Vehicle getVehicle() {
        return vehicle;
    }

    public void setVehicle(Vehicle v) {
        this.vehicle = v;
    }
}

package com.autobase.main.order;

import com.autobase.main.order.typeoforder.CargoType;
import com.autobase.main.Vehicle.Vehicle;

import java.io.*;
import java.util.List;

public abstract class Order implements Externalizable {
    private static final long serialVersionUID = 1L;

    protected String from;
    protected String to;
    protected CargoType cargoType;
    protected float cargoWeight;
    protected Vehicle vehicle;

    public static float GLOBAL_RATE = 1.0f;

    public Order() {}

    @Override
    public void writeExternal(ObjectOutput out) throws IOException {
        out.writeUTF(from != null ? from : "");
        out.writeUTF(to != null ? to : "");
        out.writeObject(cargoType);
        out.writeFloat(cargoWeight);
        out.writeObject(vehicle);
    }

    @Override
    public void readExternal(ObjectInput in) throws IOException, ClassNotFoundException {
        this.from = in.readUTF();
        this.to = in.readUTF();
        this.cargoType = (CargoType) in.readObject();
        this.cargoWeight = in.readFloat();
        this.vehicle = (Vehicle) in.readObject();
    }

    public abstract void input();

    public abstract void print();

    @Override
    public abstract String toString();

    public boolean canMergeWith(Order other) {
        return this.cargoType == other.cargoType && this.to.equals(other.to);
    }

    public void mergeWeight(float w) {
        this.cargoWeight += w;
    }

    public int loadFields(List<String> fields, int startIndex) {
        int i = startIndex;
        this.from = fields.get(i++);
        this.to = fields.get(i++);
        this.cargoType = CargoType.valueOf(fields.get(i++));
        this.cargoWeight = Float.parseFloat(fields.get(i++));
        return i;
    }

    public String getFrom() {
        return from;
    }

    public String getTo() {
        return to;
    }

    public CargoType getCargoType() {
        return cargoType;
    }

    public float getWeight() {
        return cargoWeight;
    }

    public Vehicle getVehicle() {
        return vehicle;
    }

    public void setVehicle(Vehicle v) {
        this.vehicle = v;
    }
}

package com.autobase.main.order;

import java.io.*;
import java.util.*;

public class OrderRepository {
    private static final String ORDERS_FILE = "orders.dat";

    public static void saveOrders(List<Order> orders) {
        try (ObjectOutputStream oos = new ObjectOutputStream(new FileOutputStream(ORDERS_FILE))) {
            oos.writeObject(new ArrayList<>(orders));
            System.out.println("Orders saved to " + ORDERS_FILE);
        } catch (IOException e) {
            System.err.println("Error saving orders: " + e.getMessage());
        }
    }

    @SuppressWarnings("unchecked")
    public static List<Order> loadOrders() {
        File file = new File(ORDERS_FILE);
        if (file.exists()) {
            try (ObjectInputStream ois = new ObjectInputStream(new FileInputStream(ORDERS_FILE))) {
                List<Order> loadedOrders = (List<Order>) ois.readObject();
                System.out.println("Orders loaded from " + ORDERS_FILE);
                return loadedOrders;
            } catch (IOException | ClassNotFoundException e) {
                System.err.println("Error loading orders: " + e.getMessage());
                return new ArrayList<>();
            }
        } else {
            System.out.println("No existing order database found.");
            return new ArrayList<>();
        }
    }

    public static void deleteOrdersFile() {
        File file = new File(ORDERS_FILE);
        if (file.exists() && file.delete()) {
            System.out.println("Orders file deleted.");
        }
    }
}

